import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class PrettyPrintVisitorTest {

    @Test
    public void exprToString_SimpleValue_ReturnsCorrectString() {
        Expression expr = new Value("10");
        String result = PrettyPrintVisitor.exprToString(expr);
        assertEquals("10", result);
    }

    @Test
    public void exprToString_ComplexFunctionCall_ReturnsCorrectString() {
        FunctionScript functionScript = new FunctionScript(new VarExpr("x"), 2, new BinaryExpr(new ConstExpr(1), "+", new ConstExpr(3)));
        Expression expr = functionScript.getFunc();
        String result = PrettyPrintVisitor.exprToString(expr);
        assertEquals("(x+3)", result);
    }

    @Test
    public void visitAssignExpr_AssignExpression_PrintsCorrectly() {
        AssingExpr expr = new AssingExpr(new VarExpr("x"), new ConstExpr(10));
        PrettyPrintVisitor visitor = new PrettyPrintVisitor();
        String result = visitor.visit(expr).toString();
        assertEquals("x <- 10", result);
    }

    @Test
    public void visitAssignExpr_AssignExpressionWithAlias_PrintsCorrectly() {
        AliasExpr aliasExpr = new AliasExpr(new VarExpr("y"), "z");
        AssingExpr expr = new AssingExpr(aliasExpr, new ConstExpr(20));
        PrettyPrintVisitor visitor = new PrettyPrintVisitor();
        String result = visitor.visit(expr).toString();
        assertEquals("z <- 20", result);
    }

    @Test
    public void visitBinaryExpr_BinaryExpression_PrintsCorrectly() {
        BinaryExpr expr = new BinaryExpr(new ConstExpr(1), "+", new ConstExpr(2));
        PrettyPrintVisitor visitor = new PrettyPrintVisitor();
        String result = visitor.visit(expr).toString();
        assertEquals("1+2", result);
    }

    @Test
    public void visitBinaryExpr_BinaryExpressionWithAlias_PrintsCorrectly() {
        AliasExpr aliasExpr = new AliasExpr(new VarExpr("a"), "b");
        BinaryExpr expr = new BinaryExpr(aliasExpr, "+", new ConstExpr(3));
        PrettyPrintVisitor visitor = new PrettyPrintVisitor();
        String result = visitor.visit(expr).toString();
        assertEquals("b+3", result);
    }

